package admin

const pageTemplates = `
{{define "head"}}<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/admin.css">{{end}}
{{define "brand"}}<a class="brand" href="/">Immich <span>to</span> Amazon Photos</a>{{end}}
{{define "login"}}<!doctype html><html lang="en"><head>{{template "head"}}<title>Sign in | Immich to Amazon</title></head>
<body><main class="narrow">{{template "brand"}}<h1>Sign in</h1><p>Local control for your original-media backups. Use the passphrase from your mounted admin secret.</p>
<form class="stack" method="post" action="/login"><input type="hidden" name="csrf" value="{{.CSRF}}">
<label>Admin passphrase <input type="password" name="password" autocomplete="current-password" required autofocus></label><button>Sign in</button></form>
<p class="note">Keep this dashboard on localhost or a trusted private network.</p></main></body></html>{{end}}
{{define "index"}}<!doctype html><html lang="en"><head>{{template "head"}}<title>Backup control | Immich to Amazon</title></head>
<body><main><header>{{template "brand"}}<form method="post" action="/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="quiet">Sign out</button></form></header>
<div class="page-title"><div><h1>Backup control</h1><p>Independent accounts. Original files. No cloud-media deletion.</p></div>{{if .Writable}}<a class="button" href="/accounts/new">Add account</a>{{end}}</div>
{{if not .Writable}}<p class="notice">Configuration is read-only. Start with an explicit config path and without --account to edit accounts. Account controls remain available.</p>{{end}}
{{range .Accounts}}<section class="account" aria-label="Account {{.Account.ID}}"><div class="account-heading"><h2>{{.Account.ID}}</h2><span class="state">{{if .Status.Paused}}Paused / {{.Status.PauseReason}}{{else if ne .Code "ok"}}{{.Code}}{{else}}Enabled{{end}}</span></div>
<p class="scope">Source: {{if .Account.Library}}whole accessible library{{else}}{{len .Account.AlbumIDs}} selected albums{{end}} <span>/</span> Albums: {{if eq .Account.AlbumMode "all_accessible"}}all accessible{{else if eq .Account.AlbumMode "selected"}}selected{{else}}not mirrored{{end}} <span>/</span> Destination: Amazon {{.Account.AmazonRegion}}</p>
<p class="note">Filters: {{range $i, $media := .Policy.MediaTypes}}{{if $i}}, {{end}}{{$media}}{{end}} · max original {{if .Policy.MaxOriginalBytes}}{{.Policy.MaxOriginalBytes}} bytes{{else}}unlimited{{end}} · RAW {{if .Policy.SkipRAW}}skipped{{else}}included{{end}} · archive {{if .Policy.ArchivedIncluded}}included{{else}}excluded{{end}} · excluded tags {{len .Policy.ExcludedTags}}. Filters never delete media, remove album membership or authorize trash.</p>
{{if .Status.Exclusions}}<details><summary>Excluded assets by reason</summary><dl class="diagnostics">{{range $code, $count := .Status.Exclusions}}<dt><code>{{$code}}</code></dt><dd>{{$count}}</dd>{{end}}</dl></details>{{end}}
{{if ne .Code "ok"}}<p role="status">Status unavailable: <code>{{.Code}}</code>. Check mounted credentials or run diagnosis.</p>{{end}}
<dl class="queue" aria-label="Media queue"><div><dt>Pending</dt><dd>{{.Status.Pending}}</dd></div><div><dt>Staged</dt><dd>{{.Status.Staged}}</dd></div><div><dt>Running</dt><dd>{{.Status.Running}}</dd></div><div><dt>Unconfirmed</dt><dd>{{.Status.Unconfirmed}}</dd></div><div><dt>Confirmed</dt><dd>{{.Status.Confirmed}}</dd></div><div><dt>Failed</dt><dd>{{.Status.Failed}}</dd></div><div><dt>Blocked</dt><dd>{{.Status.Blocked}}</dd></div><div><dt>Deferred</dt><dd>{{.Status.Deferred}}</dd></div><div><dt>Existing</dt><dd>{{.Status.Existing}}</dd></div><div><dt>Deletion pending</dt><dd>{{.Status.DeletePending}}</dd></div><div><dt>In Amazon trash</dt><dd>{{.Status.Deleted}}</dd></div><div><dt>Skipped</dt><dd>{{.Status.Skipped}}</dd></div></dl>
{{if .Status.TransferWindow}}<p class="note">Transfer window: {{.Status.TransferWindow.Timezone}} {{.Status.TransferWindow.Start}}–{{.Status.TransferWindow.End}} · {{if .Status.TransferWindow.Open}}open{{else}}closed{{end}}{{if .Status.TransferWindow.NextOpening}}, next opening <time datetime="{{.Status.TransferWindow.NextOpening.Format "2006-01-02T15:04:05Z07:00"}}">{{.Status.TransferWindow.NextOpening.Format "2006-01-02 15:04 MST"}}</time>{{end}}. Deferred: {{.Status.Deferred}}{{if .Status.DeferralReason}} ({{.Status.DeferralReason}}){{end}}.</p>{{end}}
<p class="note">Transfer rate cap: {{if .Status.BytesPerSecond}}{{.Status.BytesPerSecond}} bytes/s counting source-download and destination-upload bytes together per account{{else}}disabled{{end}}. Metadata traffic is not counted.</p>
<dl class="diagnostics" aria-label="Event, album and association backlog"><dt>Events pending</dt><dd>{{.Status.EventsPending}}</dd><dt>Events failed</dt><dd>{{.Status.EventsFailed}}</dd><dt>Albums active</dt><dd>{{.Status.AlbumsActive}}</dd><dt>Albums pending</dt><dd>{{.Status.AlbumsPending}}</dd><dt>Albums failed</dt><dd>{{.Status.AlbumsFailed}}</dd><dt>Albums unconfirmed</dt><dd>{{.Status.AlbumsUnconfirmed}}</dd><dt>Albums inaccessible</dt><dd>{{.Status.AlbumsInaccessible}}</dd><dt>Associations pending</dt><dd>{{.Status.AssociationsPending}}</dd><dt>Associations failed</dt><dd>{{.Status.AssociationsFailed}}</dd><dt>Associations unconfirmed</dt><dd>{{.Status.AssociationsUnconfirmed}}</dd><dt>Live Photo pairs</dt><dd>{{if eq .Status.LivePhotoMode "original_pair"}}{{.Status.PairsComplete}} complete · {{.Status.PairsIncomplete}} incomplete{{else}}still only (no pair claim){{end}}</dd><dt>Favorites mode</dt><dd>{{if .Status.FavoritesMode}}{{.Status.FavoritesMode}}{{else}}off{{end}}</dd><dt>Favorites applied</dt><dd>{{.Status.FavoritesApplied}}</dd><dt>Favorites pending</dt><dd>{{.Status.FavoritesPending}}</dd><dt>Favorites failed</dt><dd>{{.Status.FavoritesFailed}}</dd><dt>Favorites uncertain</dt><dd>{{.Status.FavoritesUncertain}}</dd><dt>Favorites unknown</dt><dd>{{.Status.FavoritesUnknown}}</dd></dl>
<dl class="diagnostics" aria-label="Managed workflow"><dt>Workflow</dt><dd>{{if .Status.Workflow}}{{.Status.Workflow}}{{else if .Account.ManagedWorkflow}}requested (pending first cycle){{else}}not requested{{end}}</dd>{{if .Status.WorkflowCode}}<dt>Workflow notice</dt><dd><code>{{.Status.WorkflowCode}}</code></dd>{{end}}<dt>Periodic polling</dt><dd>always enabled</dd></dl>
<p class="note">Work remaining: {{if .Status.WorkRemaining}}ready to run{{else}}none ready to run{{end}}. Incremental scan: {{if .Status.IncrementalScanning}}in progress{{else}}idle{{end}}. Last incremental reconcile: {{if .Status.LastIncremental}}<time datetime="{{.Status.LastIncremental.Format "2006-01-02T15:04:05Z07:00"}}">{{.Status.LastIncremental.Format "2006-01-02 15:04:05 MST"}}</time>{{else}}not yet completed{{end}}.</p>
<p class="note">Scopes scanning: {{.Status.Scanning}}. Last complete reconcile: {{if .Status.LastSuccess}}<time>{{.Status.LastSuccess.Format "2006-01-02 15:04:05 MST"}}</time>{{else}}not yet completed{{end}}.</p>
{{if .Status.Errors}}<details open><summary>Errors requiring attention</summary><dl class="diagnostics">{{range $code, $count := .Status.Errors}}<dt><code>{{$code}}</code></dt><dd>{{$count}}</dd>{{end}}</dl></details>{{end}}
<form class="actions" method="post"><input type="hidden" name="csrf" value="{{$.CSRF}}">
{{if .Status.Paused}}<button formaction="/accounts/{{.Account.ID}}/resume">Resume</button>{{else}}<button formaction="/accounts/{{.Account.ID}}/pause">Pause</button>{{end}}
<button class="quiet" formaction="/accounts/{{.Account.ID}}/retry">Retry eligible errors</button><button class="quiet" formaction="/accounts/{{.Account.ID}}/doctor">Run diagnosis</button>{{if $.Writable}}<a href="/accounts/{{.Account.ID}}/edit">Edit account</a>{{end}}
</form><p class="note">Retry preserves uncertain writes and manual pauses; it never blindly repeats an upload.</p>
{{if $.Writable}}<details><summary>Remove this account</summary><p>Stops scheduling this account. Local history and cloud media are preserved.</p><form method="post" action="/accounts/{{.Account.ID}}/remove"><input type="hidden" name="csrf" value="{{$.CSRF}}"><button class="danger">Remove account from configuration</button></form></details>{{end}}
</section>{{else}}<section class="empty"><h2>Your first backup starts here.</h2><p>Add an Immich source, choose an explicit album scope, and connect an Amazon Photos destination using mounted secret files.</p>{{if .Writable}}<a href="/accounts/new">Configure first account</a>{{end}}</section>{{end}}{{if .Orphans}}<section class="account" aria-label="Workflow cleanup"><h2>Workflow cleanup needs attention</h2><p class="note">These owned workflows belong to accounts that are no longer configured. Re-add the account with its mounted Workflow credential and set <code>managed_workflow: false</code>, then run <code>workflow remove --apply</code>.</p><dl class="diagnostics">{{range .Orphans}}<dt>{{.Account}}</dt><dd>{{.State}} <code>{{.Code}}</code></dd>{{end}}</dl></section>{{end}}
<footer>Refresh this page for current durable queue counts. Remote failures do not change local readiness.</footer></main></body></html>{{end}}
{{define "editor"}}<!doctype html><html lang="en"><head>{{template "head"}}<title>Account | Immich to Amazon</title></head><body><main class="editor">
{{template "brand"}}<nav><a href="/">Back to overview</a></nav><h1>Account settings</h1><p>Source and destination credentials stay in separate mounted files. Enter paths, never secret values.</p>
<form class="stack" method="post" action="/accounts/save"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="original_id" value="{{.Original}}">
<label>Account ID <input name="id" value="{{.Account.ID}}" pattern="[a-zA-Z0-9][a-zA-Z0-9_-]{0,127}" {{if .Original}}readonly{{end}} required aria-describedby="identity-note"></label><p class="note" id="identity-note">Stable, unique ID. Use a new ID to connect different cloud identities.</p>
<fieldset><legend>Source / Immich</legend><div class="stack">
<label>Server URL <input type="url" name="immich_url" value="{{.Account.ImmichURL}}" placeholder="https://photos.example.net" required></label>
<label>API key mounted file <input name="key_file" value="{{.Account.APIKeyFile}}" placeholder="/run/secrets/immich_key" required></label>
<div><button class="quiet" formaction="/accounts/discover" formnovalidate>List visible albums</button></div>
{{if .Albums}}<div class="album-list"><p>Add albums to the selection below:</p>{{range .Albums}}<label class="check"><input type="checkbox" name="album_id" value="{{.ID}}"><span>{{.Name}} <small>{{.Count}} assets</small></span></label>{{end}}</div>{{end}}
<label>Selected album IDs <textarea name="album_ids" rows="4" aria-describedby="scope-note">{{range .Account.AlbumIDs}}{{.}}
{{end}}</textarea></label><p class="note" id="scope-note">One ID per line, or comma-separated. Choose albums OR explicitly enable the whole library, never both.</p>
<label class="check"><input type="checkbox" name="library" {{if .Account.Library}}checked{{end}}><span>Explicitly sync the whole accessible library</span></label>
</div></fieldset><fieldset><legend>Eligibility filters</legend><div class="stack">
<p class="note">Filters choose what may be uploaded. They never delete media, remove album membership, or authorize trash. Source-hidden, trashed, offline and unsupported assets stay excluded regardless.</p>
<div class="actions"><label class="check"><input type="checkbox" name="media_image" {{if .Policy.Includes "image"}}checked{{end}}><span>Images</span></label><label class="check"><input type="checkbox" name="media_video" {{if .Policy.Includes "video"}}checked{{end}}><span>Videos</span></label></div>
<label>Maximum original size in bytes <input type="number" name="max_original_bytes" min="0" step="1" value="{{if .Policy.MaxOriginalBytes}}{{.Policy.MaxOriginalBytes}}{{end}}" placeholder="unlimited" aria-describedby="size-note"></label><p class="note" id="size-note">Zero or empty means no limit. When a limit is set, an unknown original size is excluded until the source reports it.</p>
<label class="check"><input type="checkbox" name="skip_raw" {{if .Policy.SkipRAW}}checked{{end}}><span>Skip camera RAW originals (documented extension list)</span></label>
<label class="check"><input type="checkbox" name="include_archived" {{if .Policy.ArchivedIncluded}}checked{{end}}><span>Include archived originals</span></label>
<label>Excluded tag IDs <textarea name="excluded_tags" rows="3" aria-describedby="tag-note">{{range .Policy.ExcludedTags}}{{.}}
{{end}}</textarea></label><p class="note" id="tag-note">Stable Immich tag UUIDs, one per line or comma-separated. If the source omits tag provenance, affected assets are excluded rather than assumed untagged.</p>
<label>Live Photo mode <select name="live_photo_mode" aria-describedby="live-photo-note"><option value="still_only" {{if ne .Account.LivePhotoMode "original_pair"}}selected{{end}}>Still only (default)</option><option value="original_pair" {{if eq .Account.LivePhotoMode "original_pair"}}selected{{end}}>Original pair (still and hidden MOV)</option></select></label><p class="note" id="live-photo-note">Original pair backs up the hidden MOV companion Immich reports for an included still as a second, independent original with its own hash and Node. Nothing is muxed, converted or paired remotely; a missing or ineligible companion is reported as <code>pair_incomplete</code>. Switching modes never re-uploads, overwrites or trashes an existing Node.</p>
</div></fieldset><fieldset><legend>Transfer window</legend><div class="stack">
<label>IANA timezone <input name="transfer_timezone" value="{{with .Account.TransferWindow}}{{.Timezone}}{{end}}" placeholder="America/New_York" aria-describedby="window-note"></label>
<label>Daily start (HH:MM) <input name="transfer_window_start" value="{{with .Account.TransferWindow}}{{.Start}}{{end}}" placeholder="23:00"></label>
<label>Daily end (HH:MM) <input name="transfer_window_end" value="{{with .Account.TransferWindow}}{{.End}}{{end}}" placeholder="06:00"></label>
<p class="note" id="window-note">Leave all three empty for continuous transfers. Times are local to the timezone; a window may cross midnight. Only new uploads pause: metadata checks and album reconciliation continue, and an upload already running finishes. A window change applies without restarting.</p>
</div></fieldset><fieldset><legend>Destination / Amazon Photos</legend><div class="stack">
<label>Region code <input name="region" value="{{.Account.AmazonRegion}}" placeholder="us" required aria-describedby="region-note"></label><p class="note" id="region-note">Use your actual account region; no region is selected automatically. Run diagnosis to inspect compatibility evidence.</p>
<label>Cookie mounted file <input name="cookie_file" value="{{.Account.CookieFile}}" placeholder="/run/secrets/amazon_cookie" required></label>
<label>Album mirroring <select name="album_sync_mode">
<option value="off" {{if eq .Account.AlbumMode "off"}}selected{{end}}>Off</option>
<option value="selected" {{if eq .Account.AlbumMode "selected"}}selected{{end}}>Selected albums only</option>
<option value="all_accessible" {{if eq .Account.AlbumMode "all_accessible"}}selected{{end}}>All accessible albums</option>
<label>Favorites <select name="favorites"><option value="off" {{if ne .Account.Favorites "add_only"}}selected{{end}}>Off (no favorite writes)</option><option value="add_only" {{if eq .Account.Favorites "add_only"}}selected{{end}}>Add only (star verified nodes, never unstar)</option></select></label>
<label class="check"><input type="checkbox" name="deletions" {{if .Account.Deletions}}checked{{end}}><span>Propagate source trashing to the Amazon trash (off by default; never permanently deletes)</span></label>
<label>Deletion confirmation <input name="deletions_confirmation" value="{{.Account.DeletionConfirmation}}" autocomplete="off" aria-describedby="deletion-note"><span class="note" id="deletion-note">Enabling propagation requires the exact text ENABLE DELETIONS. Turning it off is never gated.</span></label>
</div></fieldset><fieldset><legend>Managed Immich Workflow (optional)</legend><div class="stack">
<label class="check"><input type="checkbox" name="managed_workflow" {{if .Account.ManagedWorkflow}}checked{{end}}><span>Create one owned native Workflow (never replaces periodic polling)</span></label>
<label>Workflow API key mounted file <input name="workflow_key_file" value="{{.Account.WorkflowAPIKeyFile}}" placeholder="/run/secrets/immich_workflow_key" aria-describedby="workflow-note"></label>
<label>Callback URL <input type="url" name="workflow_callback_url" value="{{.Account.WorkflowCallbackURL}}" placeholder="https://sync.example.net/events/account-id" aria-describedby="workflow-note"></label>
<label>Generated secret mounted file <input name="workflow_secret_file" value="{{.Account.WorkflowSecretFile}}" placeholder="/run/secrets/workflow_secret"></label>
<p class="note" id="workflow-note">Use a separate Immich API key with workflow.read/create/update/delete. The service generates the bearer secret into this file with mode 0600 and only ever updates or removes the Workflow UUID it persisted. Immich 2.x or a missing grant falls back to polling with a notice.</p>
</div></fieldset><div class="actions"><button>Save account</button><a href="/">Cancel</a></div></form>
</main></body></html>{{end}}
{{define "doctor"}}<!doctype html><html lang="en"><head>{{template "head"}}<title>Diagnosis | Immich to Amazon</title></head><body><main class="editor">{{template "brand"}}<nav><a href="/">Back to overview</a></nav><h1>Account diagnosis</h1><p>{{.ID}} / <code>{{.Code}}</code></p><p class="notice">Read-only probes. Upload and album-write permissions are not tested.</p><dl class="diagnostics">{{range .Checks}}<dt>{{.Name}}</dt><dd><code>{{.Code}}</code></dd>{{end}}</dl></main></body></html>{{end}}
{{define "error"}}<!doctype html><html lang="en"><head>{{template "head"}}<title>Request not completed | Immich to Amazon</title></head><body><main class="narrow">{{template "brand"}}<div role="alert"><h1>Request not completed</h1><p><code>{{.}}</code></p><p>Review your settings and mounted secret files, then try again. No secret values are shown here.</p></div><a href="/">Back to overview</a></main></body></html>{{end}}
`
